exercise.solution:
zalihe = {}

# Čitaj komande u petlji while True.
while True:
    delovi = input("> ").split()
    if not delovi:
        continue
    komanda = delovi[0]
    if komanda == "kraj":
        print("Doviđenja!")
        break
    elif komanda == "dodaj":
        naziv = delovi[1]
        kolicina = int(delovi[2])
        zalihe[naziv] = zalihe.get(naziv, 0) + kolicina
    elif komanda == "prikazi":
        if not zalihe:
            print("Nema zaliha.")
        for naziv in sorted(zalihe):
            print(f"{naziv}: {zalihe[naziv]}")
    else:
        print("Nepoznata komanda.")

